        /// <summary>Полный текст тултипа: точная подпись метода + смысл из глоссария + диапазон/дефолт + пометки.</summary>
        public static string For(ParamDef d)
        {
            var sb = new StringBuilder();
            sb.Append(d.Label);
            if (Map.TryGetValue(d.Key, out var v)) sb.Append('\n').Append(v);
            sb.Append(d.IsInt
                ? $"\nДиапазон {d.Min:0}…{d.Max:0}, по умолчанию {d.Default:0}."
                : $"\nДиапазон {d.Min:0.####}…{d.Max:0.####}, по умолчанию {d.Default:0.####}.");
            if (d.Search) sb.Append("  •  участвует в авто-подборе [авто]");
            if (!d.Tunable) sb.Append("\n(режимный — «Тщательный подбор» его не меняет)");
            return sb.ToString();
        }
